use std::collections::HashMap;

fn bump(map: &mut HashMap<String, i32>, key: String) {
    if let Some(v) = map.get(&key) {
        let new_val = v + 1;
        map.insert(key, new_val);
    } else {
        map.insert(key, 1);
    }
}

fn main() {
    let mut m = HashMap::new();
    bump(&mut m, "a".into());
    bump(&mut m, "a".into());
    bump(&mut m, "b".into());
    println!("{:?}", m);
}
